#include "config.h"
#endif

#include "libopensc/pkcs15.h"
#include "libopensc/internal.h"
#include <stdlib.h>
#include <string.h>

const char *__asan_default_options() {
  return "verbosity=0:mallocator_may_return_null=1";
}

/* private data structures */
struct driver_data {
    const uint8_t *Data;
    size_t Size;
};

static struct sc_reader_operations fuzz_ops = {0};
static struct sc_reader_driver fuzz_drv = {
    "Fuzzing reader",
    "fuzz",
    &fuzz_ops,
    NULL
};

void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
{
    struct driver_data *data;
    uint16_t c_size;
    const uint8_t *c;

    if (chunk)
        *chunk = NULL;
    if (chunk_size)
        *chunk_size = 0;

    if (!chunk || !chunk_size || !reader) {
        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
        return;
    }
    data = reader->drv_data;
    if (!data || !data->Data || data->Size < sizeof c_size) {
        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
        return;
    }

    /* parse the length of the returned data on two bytes */
    c_size = *((uint16_t *) data->Data);
    /* consume two bytes from the fuzzing data */
    data->Size -= sizeof c_size;
    data->Data += sizeof c_size;

    if (data->Size < c_size) {
        c_size = data->Size;
    }

    /* consume the bytes from the fuzzing data */
    c = data->Data;
    data->Size -= c_size;
    data->Data += c_size;

    sc_debug_hex(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL,
        "Returning fuzzing chunk", c, c_size);

    *chunk = c;
    *chunk_size = c_size;
}

static int fuzz_reader_release(sc_reader_t *reader)
{
    if (reader) {
        free(reader->drv_data);
        reader->drv_data = NULL;
    }

    return SC_SUCCESS;
}

static int fuzz_reader_connect(sc_reader_t *reader)
{
    uint16_t chunk_size;
    const uint8_t *chunk;

    fuzz_get_chunk(reader, &chunk, &chunk_size);

    if (chunk_size > reader->atr.len)
        chunk_size = reader->atr.len;
    else
        reader->atr.len = chunk_size;

    if (chunk_size > 0)
        memcpy(reader->atr.value, chunk, chunk_size);

    return SC_SUCCESS;
}

static int fuzz_reader_disconnect(sc_reader_t *reader)
{
    return SC_SUCCESS;
}

static int fuzz_reader_transmit(sc_reader_t *reader, sc_apdu_t *apdu)
{
    const uint8_t *chunk;
    uint16_t chunk_size;

    fuzz_get_chunk(reader, &chunk, &chunk_size);

    if (chunk_size >= 2) {
        /* set the SW1 and SW2 status bytes (the last two bytes of
         * the response */
        apdu->sw1 = (unsigned int)chunk[chunk_size - 2];
        apdu->sw2 = (unsigned int)chunk[chunk_size - 1];
        chunk_size -= 2;
        /* set output length and copy the returned data if necessary */
        if (chunk_size <= apdu->resplen)
            apdu->resplen = chunk_size;

        if (apdu->resplen != 0)
            memcpy(apdu->resp, chunk, apdu->resplen);
    } else {
        apdu->sw1 = 0x6D;
        apdu->sw2 = 0x00;
        apdu->resplen = 0;
    }

    return SC_SUCCESS;
}

struct sc_reader_driver *sc_get_fuzz_driver(void)
{
    fuzz_ops.release = fuzz_reader_release;
    fuzz_ops.connect = fuzz_reader_connect;
    fuzz_ops.disconnect = fuzz_reader_disconnect;
    fuzz_ops.transmit = fuzz_reader_transmit;
    return &fuzz_drv;
}

void fuzz_add_reader(struct sc_context *ctx, const uint8_t *Data, size_t Size)
{
    sc_reader_t *reader;
    struct driver_data *data;
    char name[64] = {0};

    if (!(reader = calloc(1, sizeof(*reader)))
            || !(data = (calloc(1, sizeof(*data))))) {
        free(reader);
        return;
    }

    data->Data = Data;
    data->Size = Size;

    reader->driver = &fuzz_drv;
    reader->ops = &fuzz_ops;
    reader->drv_data = data;
    snprintf(name, sizeof name - 1, "%zu random byte%s reader (%p)",
            Size, Size == 1 ? "" : "s", Data);
    reader->name = strdup(name);

    reader->ctx = ctx;
    list_append(&ctx->readers, reader);
}

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    struct sc_context *ctx = NULL;
    struct sc_card *card = NULL;
    struct sc_pkcs15_card *p15card = NULL;
    struct sc_reader *reader;
    struct sc_pkcs15_object *obj;

    sc_establish_context(&ctx, "fuzz");
    if (!ctx)
        return 0;
    /* copied from sc_release_context() */
    while (list_size(&ctx->readers)) {
        sc_reader_t *rdr = (sc_reader_t *) list_get_at(&ctx->readers, 0);
        _sc_delete_reader(ctx, rdr);
    }
    if (ctx->reader_driver->ops->finish != NULL)
        ctx->reader_driver->ops->finish(ctx);

    ctx->reader_driver = sc_get_fuzz_driver();

    fuzz_add_reader(ctx, Data, Size);

    reader = sc_ctx_get_reader(ctx, 0);
    sc_connect_card(reader, &card);
    sc_pkcs15_bind(card, NULL, &p15card);

    if (p15card) {
        const uint8_t *in, *param;
        uint16_t in_len, param_len;
        fuzz_get_chunk(reader, &in, &in_len);
        fuzz_get_chunk(reader, &param, &param_len);
        for (obj = p15card->obj_list; obj != NULL; obj = obj->next) {
            u8 buf[0xFFFF];
            size_t i;

            int decipher_flags[] = {SC_ALGORITHM_RSA_RAW,
                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
                SC_ALGORITHM_RSA_PAD_ISO9796};
            for (i = 0; i < sizeof decipher_flags/sizeof *decipher_flags; i++) {
                sc_pkcs15_decipher(p15card, obj, decipher_flags[i],
                        in, in_len, buf, sizeof buf);
            }

            i = sizeof buf;
            sc_pkcs15_derive(p15card, obj, 0,
                    in, in_len, buf, &i);

            int wrap_flags[] = {0, SC_ALGORITHM_AES_ECB, SC_ALGORITHM_AES_CBC_PAD,
                SC_ALGORITHM_AES_CBC};
            for (i = 0; i < sizeof wrap_flags/sizeof *wrap_flags; i++) {
                struct sc_pkcs15_object target_key;
                sc_pkcs15_unwrap(p15card, obj, &target_key, wrap_flags[i],
                        in, in_len, param, param_len);
                unsigned long l = sizeof buf;
                sc_pkcs15_wrap(p15card, obj, &target_key, wrap_flags[i],
                        buf, &l, in, in_len);
            }

            int signature_flags[] = {SC_ALGORITHM_RSA_RAW,
                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
                SC_ALGORITHM_RSA_PAD_ISO9796,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA1,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA256,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA384,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA512,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA224,
                SC_ALGORITHM_ECDSA_RAW, SC_ALGORITHM_ECDSA_HASH_SHA1,
                SC_ALGORITHM_ECDSA_HASH_SHA224, SC_ALGORITHM_ECDSA_HASH_SHA256,
                SC_ALGORITHM_ECDSA_HASH_SHA384, SC_ALGORITHM_ECDSA_HASH_SHA512,
                SC_ALGORITHM_GOSTR3410_RAW, SC_ALGORITHM_GOSTR3410_HASH_GOSTR3411,
                SC_ALGORITHM_GOSTR3410_HASHES,
            };
            for (i = 0; i < sizeof signature_flags/sizeof *signature_flags; i++) {
                sc_pkcs15_compute_signature(p15card, obj, signature_flags[i],
                        in, in_len, buf, sizeof buf);
        if (r < 0) {
                goto fail;
        }
        r = sc_pkcs15_read_certificate(p15card, &cert_info, &cert_out);
        if (r < 0) {
                goto fail;
        }
        key = cert_out->key;
        cert_out->key = NULL; /* adopt the key from the cert */
fail:
        if (cert_out) {
                sc_pkcs15_free_certificate(cert_out);
        }
        if (cert_info.value.value) {
                free(cert_info.value.value);
        }
        return key;
}

static sc_pkcs15_pubkey_t *
coolkey_get_public_key(sc_pkcs15_card_t *p15card, sc_cardctl_coolkey_object_t *obj, CK_KEY_TYPE key_type)
{
        sc_pkcs15_pubkey_t *key;

        key = coolkey_make_public_key(p15card->card, obj, key_type);
        if (key) {
                return key;
        }
        return coolkey_get_public_key_from_certificate(p15card, obj);
}

static int sc_pkcs15emu_coolkey_init(sc_pkcs15_card_t *p15card)
{
        static const pindata pins[] = {
                { "1", NULL, "", 0x00,
                  SC_PKCS15_PIN_TYPE_ASCII_NUMERIC,
                  32, 4, 32,
                  SC_PKCS15_PIN_FLAG_INITIALIZED,
                  -1, 0xFF,
                  SC_PKCS15_CO_FLAG_PRIVATE },
                { NULL, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 0}
        };

        /*
         * The size of the key or the algid is not really known
         * but can be derived from the certificates.
         * the cert, pubkey and privkey are a set.
         * Key usages bits taken from certificate key usage extension.
         */

        int    r, i;
        sc_card_t *card = p15card->card;
        sc_serial_number_t serial;
        int count;
        struct sc_pkcs15_object *obj;

        SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);

        memset(&serial, 0, sizeof(serial));

        /* coolkey caches a nonce once it logs in, don't keep the pin around. The card will
         * stay logged in until it's been pulled from the reader, in which case you want to reauthenticate
         * anyway */
        p15card->opts.use_pin_cache = 0;


        /* get the token info from the card */
        r = sc_card_ctl(card, SC_CARDCTL_COOLKEY_GET_TOKEN_INFO, p15card->tokeninfo);
        if (r < 0) {
                /* put some defaults in if we didn't succeed */
                p15card->tokeninfo->label = strdup("Coolkey");
                p15card->tokeninfo->manufacturer_id = strdup("Unknown");
                p15card->tokeninfo->serial_number = strdup("00000000");
        }

        /* set pins */
        sc_log(card->ctx,  "Coolkey adding pins...");
        for (i = 0; pins[i].id; i++) {
                struct sc_pkcs15_auth_info pin_info;
                struct sc_pkcs15_object   pin_obj;
                const char * label;

                memset(&pin_info, 0, sizeof(pin_info));
                memset(&pin_obj,  0, sizeof(pin_obj));

                pin_info.auth_type = SC_PKCS15_PIN_AUTH_TYPE_PIN;
                sc_pkcs15_format_id(pins[i].id, &pin_info.auth_id);
                pin_info.attrs.pin.reference     = pins[i].ref;
                pin_info.attrs.pin.flags         = pins[i].flags;
                pin_info.attrs.pin.type          = pins[i].type;
                pin_info.attrs.pin.min_length    = pins[i].minlen;
                pin_info.attrs.pin.stored_length = pins[i].storedlen;
                pin_info.attrs.pin.max_length    = pins[i].maxlen;
                pin_info.attrs.pin.pad_char      = pins[i].pad_char;
                sc_format_path(pins[i].path, &pin_info.path);
                pin_info.tries_left    = -1;

                label = pins[i].label? pins[i].label : p15card->tokeninfo->label;
                sc_log(card->ctx,  "Coolkey Adding pin %d label=%s",i, label);
                strncpy(pin_obj.label, label, SC_PKCS15_MAX_LABEL_SIZE - 1);
                pin_obj.flags = pins[i].obj_flags;

                r = sc_pkcs15emu_add_pin_obj(p15card, &pin_obj, &pin_info);
                if (r < 0)
                        LOG_FUNC_RETURN(card->ctx, r);
        }

        /* set other objects */
        r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_INIT_GET_OBJECTS, &count);
        LOG_TEST_RET(card->ctx, r, "Can not initiate objects.");

        for (i = 0; i < count; i++) {
                struct sc_cardctl_coolkey_object     coolkey_obj;
                struct sc_pkcs15_object    obj_obj;
                struct sc_pkcs15_cert_info cert_info;
                struct sc_pkcs15_pubkey_info pubkey_info;
                struct sc_pkcs15_prkey_info prkey_info;
                sc_pkcs15_pubkey_t *key = NULL;
                void *obj_info = NULL;
                int obj_type = 0;
                CK_KEY_TYPE key_type;
                CK_OBJECT_CLASS obj_class;
                size_t len;

                r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_GET_NEXT_OBJECT, &coolkey_obj);
                if (r < 0)
                        LOG_FUNC_RETURN(card->ctx, r);


                memset(&obj_obj, 0, sizeof(obj_obj));
                /* coolkey applets have label only on the certificates,
                 * but we should copy it also to the keys matching the same ID */
                coolkey_get_attribute_bytes(card, &coolkey_obj, CKA_LABEL, (u8 *)obj_obj.label, &len, sizeof(obj_obj.label));
                coolkey_get_flags(card, &coolkey_obj, &obj_obj.flags);
                if (obj_obj.flags & SC_PKCS15_CO_FLAG_PRIVATE) {
                        sc_pkcs15_format_id(pins[0].id, &obj_obj.auth_id);
                }

                r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_CLASS, &obj_class);
                if (r < 0) {
                        goto fail;
                }
                switch (obj_class) {
                case CKO_PRIVATE_KEY:
                        r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
                        /* default to CKK_RSA */
                        if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
                                key_type = CKK_RSA;
                                r = SC_SUCCESS;
                        }
                        if (r < 0) {
                                goto fail;
                        }
                        /* set the info values */
                        obj_info = &prkey_info;
                        memset(&prkey_info, 0, sizeof(prkey_info));
                        coolkey_get_id(card, &coolkey_obj, &prkey_info.id);
                        prkey_info.path = coolkey_obj.path;
                        prkey_info.key_reference = coolkey_obj.id;
                        prkey_info.native = 1;
                        coolkey_get_usage(card, &coolkey_obj, &prkey_info.usage);
                        coolkey_get_access(card, &coolkey_obj, &prkey_info.access_flags);
                        key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
                        if (key_type == CKK_RSA) {
                                obj_type = SC_PKCS15_TYPE_PRKEY_RSA;
                                if (key) {
                                        prkey_info.modulus_length =  key->u.rsa.modulus.len*8;
                                }
                        } else if (key_type == CKK_EC) {
                                obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
                                if (key) {
                                        prkey_info.field_length =  key->u.ec.params.field_length;
                                }
                        } else {
                                goto fail;
                        }
                        break;

                case CKO_PUBLIC_KEY:
                        r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
                        /* default to CKK_RSA */
                        if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
                                key_type = CKK_RSA;
                                r = SC_SUCCESS;
                        }
                        if (r < 0) {
                                goto fail;
                        }
                        key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
                        if (key == NULL) {
                                goto fail;
                        }
                        /* set the info values */
                        obj_info = &pubkey_info;
                        memset(&pubkey_info, 0, sizeof(pubkey_info));
                        r = sc_pkcs15_encode_pubkey_as_spki(card->ctx, key, &pubkey_info.direct.spki.value,
                                                                                                                                                        &pubkey_info.direct.spki.len);
                        if (r < 0)
                                goto fail;
                        coolkey_get_id(card, &coolkey_obj, &pubkey_info.id);
                        pubkey_info.path = coolkey_obj.path;
                        pubkey_info.native        = 1;
                        pubkey_info.key_reference = coolkey_obj.id;
                        coolkey_get_usage(card, &coolkey_obj, &pubkey_info.usage);
                        coolkey_get_access(card, &coolkey_obj, &pubkey_info.access_flags);
                        if (key_type == CKK_RSA) {
                                obj_type = SC_PKCS15_TYPE_PUBKEY_RSA;
                                pubkey_info.modulus_length =  key->u.rsa.modulus.len*8;
                        } else if (key_type == CKK_EC) {
                                obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
                                pubkey_info.field_length =  key->u.ec.params.field_length;
                        } else {
                                goto fail;
                        }
                        /* set the obj values */
                        obj_obj.emulated = key;
                        key = NULL;
                        break;

                case CKO_CERTIFICATE:
                        obj_info = &cert_info;
                        memset(&cert_info, 0, sizeof(cert_info));
                        coolkey_get_id(card, &coolkey_obj, &cert_info.id);
                        cert_info.path = coolkey_obj.path;
                        obj_type = SC_PKCS15_TYPE_CERT_X509;

                        /* following will find the cached cert in cert_info */
                        r = coolkey_get_certificate(card, &coolkey_obj, &cert_info.value);
                        if (r < 0) {
                                goto fail;
                        }
                        break;


                default:
                        /* no other recognized types which are stored 'on card' */
                        break;
                }
                if (obj_info == NULL) {
                        continue;
                }

                r = sc_pkcs15emu_object_add(p15card, obj_type, &obj_obj, obj_info);
                if (r != SC_SUCCESS)
                        sc_log(card->ctx, "sc_pkcs15emu_object_add() returned %d", r);
fail:
                if (key) { sc_pkcs15_free_pubkey(key); }

        }
        r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_FINAL_GET_OBJECTS, &count);
        LOG_TEST_RET(card->ctx, r, "Can not finalize objects.");

        /* Iterate over all the created objects and fill missing labels */
        for (obj = p15card->obj_list; obj != NULL; obj = obj->next) {
                struct sc_pkcs15_id *id = NULL;
                struct sc_pkcs15_object *cert_object;

                /* label non-empty -- do not overwrite */
                if (obj->label[0] != '\0')
                        continue;

                switch (obj->type & SC_PKCS15_TYPE_CLASS_MASK) {
                case SC_PKCS15_TYPE_PUBKEY:
                        id = &((struct sc_pkcs15_pubkey_info *)obj->data)->id;
                        break;
                case SC_PKCS15_TYPE_PRKEY:
                        id = &((struct sc_pkcs15_prkey_info *)obj->data)->id;
                        break;
                default:
                        /* We do not care about other objects */
                        continue;
                }
                r = sc_pkcs15_find_cert_by_id(p15card, id, &cert_object);
                if (r != 0)
                        continue;

                sc_log(card->ctx, "Copy label \"%s\" from cert to key object",
                        cert_object->label);
                memcpy(obj->label, cert_object->label, SC_PKCS15_MAX_LABEL_SIZE);
        }

int sc_pkcs15emu_object_add(sc_pkcs15_card_t *p15card, unsigned int type,
        const sc_pkcs15_object_t *in_obj, const void *data)
{
        sc_pkcs15_object_t *obj;
        unsigned int    df_type;
        size_t          data_len;

        obj = calloc(1, sizeof(*obj));
        if (!obj)
                return SC_ERROR_OUT_OF_MEMORY;
        memcpy(obj, in_obj, sizeof(*obj));
        obj->type  = type;

        switch (type & SC_PKCS15_TYPE_CLASS_MASK) {
        case SC_PKCS15_TYPE_AUTH:
                df_type  = SC_PKCS15_AODF;
                data_len = sizeof(struct sc_pkcs15_auth_info);
                break;
        case SC_PKCS15_TYPE_PRKEY:
                df_type  = SC_PKCS15_PRKDF;
                data_len = sizeof(struct sc_pkcs15_prkey_info);
                break;
        case SC_PKCS15_TYPE_PUBKEY:
                df_type = SC_PKCS15_PUKDF;
                data_len = sizeof(struct sc_pkcs15_pubkey_info);
                break;
        case SC_PKCS15_TYPE_CERT:
                df_type = SC_PKCS15_CDF;
                data_len = sizeof(struct sc_pkcs15_cert_info);
                break;
        case SC_PKCS15_TYPE_DATA_OBJECT:
                df_type = SC_PKCS15_DODF;
                data_len = sizeof(struct sc_pkcs15_data_info);
                break;
        default:
                sc_log(p15card->card->ctx, "Unknown PKCS15 object type %d", type);
                free(obj);
                return SC_ERROR_INVALID_ARGUMENTS;
        }

        obj->data = calloc(1, data_len);
        if (obj->data == NULL) {
                free(obj);
                return SC_ERROR_OUT_OF_MEMORY;
        }
        memcpy(obj->data, data, data_len);

        obj->df = sc_pkcs15emu_get_df(p15card, df_type);
        sc_pkcs15_add_object(p15card, obj);

        return SC_SUCCESS;
}
